package com.bemo.hr.product.pack;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/api/v1/platform/industry-packs")@RequiredArgsConstructor@PreAuthorize("hasRole('SUPER_ADMIN')")
public class IndustryPackController{private final IndustryPackService service;@GetMapping List<IndustryPackApi.PackResponse> catalog(){return service.catalog();}@PostMapping("/{code}/install")IndustryPackApi.PackResponse install(@PathVariable String code,@Valid@RequestBody IndustryPackApi.InstallRequest request,Authentication auth){return service.install(code,request,auth.getName());}@PostMapping("/{code}/upgrade")IndustryPackApi.PackResponse upgrade(@PathVariable String code,@Valid@RequestBody IndustryPackApi.UpgradeRequest request,Authentication auth){return service.upgrade(code,request,auth.getName());}@PutMapping("/{code}/settings")IndustryPackApi.PackResponse settings(@PathVariable String code,@Valid@RequestBody IndustryPackApi.SettingsRequest request,Authentication auth){return service.updateSettings(code,request,auth.getName());}@PostMapping("/{code}/steps/{stepKey}")IndustryPackApi.PackResponse step(@PathVariable String code,@PathVariable String stepKey,@Valid@RequestBody IndustryPackApi.StepRequest request,Authentication auth){return service.completeStep(code,stepKey,request,auth.getName());}}
